WITH cleaned AS (SELECT id, session_id, event_type, event_time, duration_sec, CEIL(duration_sec) AS duration_sec_whole FROM web_events WHERE session_id IN (5, 11, 27, 28)) SELECT id, session_id, event_type, event_time, duration_sec, duration_sec_whole, PERCENT_RANK() OVER w_recent AS duration_sec_whole_percent_rank, SUM(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_duration_sec, AVG(duration_sec_whole) OVER w_ordered AS duration_sec_whole_avg_2_prior FROM cleaned WINDOW w_recent AS (ORDER BY duration_sec_whole), w_ordered AS (PARTITION BY session_id, event_type ORDER BY duration_sec_whole, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING)
